message.content:
Here's a standalone HTML page that converts Celsius and Fahrenheit as you type, with accessible error labels for invalid input.
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Celsius ↔ Fahrenheit Converter</title>
<style>
  :root {
    color-scheme: light dark;
    --bg: #eef1f6;
    --panel: #ffffff;
    --text: #14171c;
    --muted: #5a6472;
    --border: #c3cad4;
    --accent: #2f6fed;
    --error: #b3261e;
    --error-bg: #fdecea;
    --shadow: 0 10px 30px rgba(20, 23, 28, .08);
  }

  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #0e1116;
      --panel: #171b22;
      --text: #e9edf3;
      --muted: #9aa5b4;
      --border: #333c48;
      --accent: #8ab0ff;
      --error: #ff9a90;
      --error-bg: #2b1613;
      --shadow: 0 10px 30px rgba(0, 0, 0, .5);
    }
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    padding: 1.5rem;
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.5;
  }

  main {
    width: 100%;
    max-width: 40rem;
    background: var(--panel);
    border-radius: 1rem;
    padding: clamp(1.25rem, 4vw, 2.25rem);
    box-shadow: var(--shadow);
  }

  h1 {
    margin: 0 0 .35rem;
    font-size: clamp(1.35rem, 3.5vw, 1.6rem);
    letter-spacing: -.01em;
  }

  .intro {
    margin: 0 0 1.5rem;
    color: var(--muted);
    font-size: .95rem;
  }

  .converter {
    display: grid;
    gap: 1rem;
    grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  }

  .field {
    display: flex;
    flex-direction: column;
    gap: .4rem;
  }

  label {
    font-weight: 600;
    font-size: .9rem;
  }

  .input-wrap {
    position: relative;
    display: flex;
    align-items: center;
  }

  input {
    width: 100%;
    font: inherit;
    font-size: 1.25rem;
    font-variant-numeric: tabular-nums;
    padding: .6rem 2.75rem .6rem .75rem;
    color: inherit;
    background: transparent;
    border: 1.5px solid var(--border);
    border-radius: .625rem;
    transition: border-color .15s ease, background-color .15s ease;
  }

  input::placeholder { color: var(--muted); opacity: .7; }

  input:focus-visible {
    outline: 3px solid var(--accent);
    outline-offset: 2px;
    border-color: var(--accent);
  }

  input[aria-invalid="true"] {
    border-color: var(--error);
    background: var(--error-bg);
  }

  .unit {
    position: absolute;
    right: .8rem;
    color: var(--muted);
    font-size: 1rem;
    pointer-events: none;
  }

  .error {
    margin: 0;
    min-height: 1.25rem;
    font-size: .85rem;
    font-weight: 500;
    color: var(--error);
  }

  .formula {
    margin: 1.5rem 0 0;
    padding-top: 1rem;
    border-top: 1px solid var(--border);
    color: var(--muted);
    font-size: .85rem;
  }

  .formula code {
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  }
</style>
</head>
<body>
<main>
  <h1>Celsius ↔ Fahrenheit</h1>
  <p class="intro">Type in either field — the other one updates as you type.</p>

  <div class="converter">
    <div class="field">
      <label for="celsius">Celsius</label>
      <div class="input-wrap">
        <input id="celsius" name="celsius" type="text" inputmode="decimal"
               autocomplete="off" spellcheck="false"
               placeholder="0" aria-invalid="false"
               aria-describedby="celsius-error">
        <span class="unit" aria-hidden="true">°C</span>
      </div>
      <p class="error" id="celsius-error" aria-live="polite"></p>
    </div>

    <div class="field">
      <label for="fahrenheit">Fahrenheit</label>
      <div class="input-wrap">
        <input id="fahrenheit" name="fahrenheit" type="text" inputmode="decimal"
               autocomplete="off" spellcheck="false"
               placeholder="32" aria-invalid="false"
               aria-describedby="fahrenheit-error">
        <span class="unit" aria-hidden="true">°F</span>
      </div>
      <p class="error" id="fahrenheit-error" aria-live="polite"></p>
    </div>
  </div>

  <p class="formula">
    <code>°F = °C × 9/5 + 32</code> &nbsp;·&nbsp; <code>°C = (°F − 32) × 5/9</code>
  </p>
</main>

<script>
(function () {
  'use strict';

  // A complete, well-formed number (allows 1., .5, 1e3, -40, +7)
  var NUMBER_RE  = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
  // A prefix of a number the user is still typing ("-", "1.", "1e+")
  var PARTIAL_RE = /^(?=[+-.\d])[+-]?(?:\d*\.?\d*)(?:[eE][+-]?\d*)?$/;

  var fields = {
    celsius: {
      input: document.getElementById('celsius'),
      error: document.getElementById('celsius-error'),
      convert: function (c) { return c * 9 / 5 + 32; }
    },
    fahrenheit: {
      input: document.getElementById('fahrenheit'),
      error: document.getElementById('fahrenheit-error'),
      convert: function (f) { return (f - 32) * 5 / 9; }
    }
  };

  var partner = { celsius: 'fahrenheit', fahrenheit: 'celsius' };

  // Trim floating-point noise and keep the display readable.
  function format(n) {
    if (!Number.isFinite(n)) return '';
    var cleaned = Number(n.toPrecision(12));
    return String(Number(cleaned.toFixed(6)));
  }

  function setError(key, message) {
    var f = fields[key];
    f.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    f.error.textContent = message || '';
  }

  function parse(raw) {
    var value = raw.trim();
    if (value === '') return { state: 'empty' };

    if (NUMBER_RE.test(value)) {
      var n = Number(value);
      if (Number.isFinite(n)) return { state: 'valid', value: n };
      return { state: 'invalid', message: 'That number is too large to convert.' };
    }

    if (PARTIAL_RE.test(value)) return { state: 'incomplete' };

    return { state: 'invalid', message: 'Enter a number, like -40, 21.5 or 98.6.' };
  }

  function update(sourceKey) {
    var source    = fields[sourceKey];
    var targetKey = partner[sourceKey];
    var target    = fields[targetKey];
    var result    = parse(source.input.value);

    if (result.state === 'valid') {
      setError(sourceKey, null);
      target.input.value = format(source.convert(result.value));
      setError(targetKey, null);
    } else {
      // Empty, half-typed, or invalid: clear the partner field.
      setError(sourceKey, result.state === 'invalid' ? result.message : null);
      target.input.value = '';
      setError(targetKey, null);
    }
  }

  Object.keys(fields).forEach(function (key) {
    fields[key].input.addEventListener('input', function () { update(key); });
  });
})();
</script>
</body>
</html>
```
### Live Conversion & Accessible Validation

Here's how the page handles real-time updates and clear error feedback.

- **Two-way live conversion** — Typing in either field instantly recalculates the other using the standard formulas, so you can start from Celsius or Fahrenheit.
- **Accessible invalid input labeling** — Each input has `aria-invalid` and `aria-describedby` pointing to a live error message. When you enter something like "abc", the field turns red and a polite screen-reader announcement explains the problem.
- **Smart partial input handling** — Incomplete numbers like "-" or "1e+" are treated as still being typed, so the partner field clears without showing an error until the input is truly invalid.
- **Readable number formatting** — Results are rounded to six decimal places and stripped of floating-point noise, keeping the display clean.
---

**Optimization Tip:** You can adjust the rounding precision by changing the `6` in `cleaned.toFixed(6)` inside the `format` function.

