(function () {
  'use strict';

  var NUMBER_RE = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
  var PARTIAL_RE = /^(?=[+-.\d])[+-]?(?:\d*\.?\d*)(?:[eE][+-]?\d*)?$/;

  var fields = {
    celsius: {
      input: document.getElementById('celsius'),
      error: document.getElementById('celsius-error'),
      convert: function (c) { return c * 9 / 5 + 32; }
    },
    fahrenheit: {
      input: document.getElementById('fahrenheit'),
      error: document.getElementById('fahrenheit-error'),
      convert: function (f) { return (f - 32) * 5 / 9; }
    }
  };

  var partner = { celsius: 'fahrenheit', fahrenheit: 'celsius' };

  function format(n) {
    if (!isFinite(n)) return '';
    return String(Number(n.toPrecision(12)));
  }

  function setError(key, message) {
    var f = fields[key];
    f.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    f.error.textContent = message || '';
  }

  function parse(raw) {
    var value = raw.trim();
    if (value === '') return { state: 'empty' };
    if (NUMBER_RE.test(value)) {
      var n = Number(value);
      if (isFinite(n)) return { state: 'valid', value: n };
      return { state: 'invalid', message: 'That number is too large to convert.' };
    }
    if (PARTIAL_RE.test(value)) return { state: 'incomplete' };
    return { state: 'invalid', message: 'Enter a number, like -40, 21.5 or 98.6.' };
  }

  function update(sourceKey) {
    var source = fields[sourceKey];
    var targetKey = partner[sourceKey];
    var target = fields[targetKey];
    var result = parse(source.input.value);

    if (result.state === 'valid') {
      setError(sourceKey, null);
      target.input.value = format(source.convert(result.value));
      setError(targetKey, null);
    } else {
      setError(sourceKey, result.state === 'invalid' ? result.message : null);
      target.input.value = '';
      setError(targetKey, null);
    }
  }

  Object.keys(fields).forEach(function (key) {
    fields[key].input.addEventListener('input', function () { update(key); });
  });
})();
